package load

import (
	"bytes"
	"fmt"
	"os"
	"path/filepath"
	"slices"
	"strings"
)

// LinkGoName is the generated file auto-link puts in each main package: blank
// imports of every package of the module that declares routes, crons or other
// registrations through decorators, so the program serves them without a
// hand-written import. vuka build, run, test and vet inject it through the
// overlay; vuka gen writes it to disk for plain go tools.
const LinkGoName = "vuka_link_gen.go"

// noLinkDirective, on its own line above a package clause, opts a package out
// of auto-link: a declarer package it names isn't linked, and a main package
// it names gets no generated imports (the app curates its own).
const noLinkDirective = "//vuka:nolink"

// LinkedMain is one main package auto-link generated a file for.
type LinkedMain struct {
	Dir     string   // the main package's directory
	Imports []string // the import paths it blank-imports, sorted
}

// AutoLink returns, for each main package of the module at root, the
// generated file linking every declarer package: a package with at least one
// declaration whose decorators include a declarer, a type decorator or a
// composed decorator (Generated.Declares), found when pkgs were transpiled
// into gens. Every declarer package is linked into every main — a blank
// import a main already reaches again is harmless, and inits of declarer
// packages only register into registries — except that a package under
// examples/ is linked only into a main of the same example. Declarations in
// test files don't count, and //vuka:nolink above a package clause opts a
// package — or a whole main — out. A main whose imports come out empty gets a
// file only when one is already on disk (gen -inplace wrote it earlier), so
// the stale one never breaks the build.
func AutoLink(root, modPath string, pkgs []*Package, gens []Generated) ([]Generated, []LinkedMain, error) {
	root = realPath(root)
	declares := map[string]bool{}
	for _, g := range gens {
		if g.Declares && !strings.HasSuffix(g.Target, "_vuka_test.go") {
			declares[filepath.Dir(g.Target)] = true
		}
	}
	type declarer struct{ path, rel string }
	var declarers []declarer
	for _, p := range pkgs {
		if !declares[p.Dir] || p.Name == "main" || strings.HasSuffix(p.Name, "_test") || p.NoLink {
			continue
		}
		rel, err := filepath.Rel(root, p.Dir)
		if err != nil {
			continue
		}
		declarers = append(declarers, declarer{p.ImportPath, filepath.ToSlash(rel)})
	}
	slices.SortFunc(declarers, func(a, b declarer) int { return strings.Compare(a.path, b.path) })
	declarers = slices.CompactFunc(declarers, func(a, b declarer) bool { return a.path == b.path })

	mains, err := mainPackages(root)
	if err != nil {
		return nil, nil, err
	}
	var out []Generated
	var linked []LinkedMain
	for _, m := range mains {
		if m.noLink {
			continue
		}
		rel, err := filepath.Rel(root, m.dir)
		if err != nil {
			continue
		}
		ex := exampleOf(filepath.ToSlash(rel))
		var imports []string
		for _, d := range declarers {
			if d.rel == filepath.ToSlash(rel) {
				continue // the main's own directory
			}
			if dx := exampleOf(d.rel); dx != "" && dx != ex {
				continue // another example's package
			}
			if !visible(filepath.ToSlash(rel), d.rel) {
				continue // internal to a tree the main isn't in
			}
			imports = append(imports, d.path)
		}
		if len(imports) == 0 && !fileExists(filepath.Join(m.dir, LinkGoName)) {
			continue
		}
		out = append(out, Generated{Target: filepath.Join(m.dir, LinkGoName), Src: linkSrc(imports)})
		linked = append(linked, LinkedMain{Dir: m.dir, Imports: imports})
	}
	return out, linked, nil
}

// visible reports whether the package at slash path imported (relative to
// the module root) may be imported from the one at importer, by Go's rule
// for internal directories: only from within the tree rooted at the parent
// of its last internal element.
func visible(importer, imported string) bool {
	parts := strings.Split(imported, "/")
	for i := len(parts) - 1; i >= 0; i-- {
		if parts[i] != "internal" {
			continue
		}
		parent := strings.Join(parts[:i], "/")
		return parent == "" || importer == parent || strings.HasPrefix(importer, parent+"/")
	}
	return true
}

// exampleOf is the examples/<name> prefix of a slash path relative to the
// module root, or "" when it isn't under examples/.
func exampleOf(rel string) string {
	rest, ok := strings.CutPrefix(rel, "examples/")
	if !ok {
		return ""
	}
	name, _, _ := strings.Cut(rest, "/")
	return "examples/" + name
}

// linkSrc is the content of a main package's LinkGoName file.
func linkSrc(imports []string) []byte {
	var b bytes.Buffer
	b.WriteString("// Code generated by vuka. DO NOT EDIT.\n\n")
	b.WriteString("// Every package of the module that declares routes, crons or other\n")
	b.WriteString("// registrations through decorators, linked so the program serves them\n")
	b.WriteString("// without a hand-written import (//vuka:nolink above a package clause\n")
	b.WriteString("// opts a package, or this main, out).\n\npackage main\n")
	if len(imports) > 0 {
		b.WriteString("\nimport (\n")
		for _, p := range imports {
			fmt.Fprintf(&b, "\t_ %q\n", p)
		}
		b.WriteString(")\n")
	}
	return b.Bytes()
}

// mainPkg is a directory holding a main package.
type mainPkg struct {
	dir    string
	noLink bool
}

// mainPackages finds the module's main packages: every directory under root —
// hidden and _-prefixed directories, testdata, vendor, node_modules, nested
// modules and gen's build output left out — whose Go or Vuka source (tests
// and LinkGoName aside) says package main.
func mainPackages(root string) ([]mainPkg, error) {
	var out []mainPkg
	err := filepath.WalkDir(root, func(path string, e os.DirEntry, err error) error {
		if err != nil {
			return nil
		}
		if !e.IsDir() {
			return nil
		}
		name := e.Name()
		if path != root {
			if strings.HasPrefix(name, ".") || strings.HasPrefix(name, "_") ||
				name == "testdata" || name == "vendor" || name == "node_modules" ||
				fileExists(filepath.Join(path, "go.mod")) || fileExists(filepath.Join(path, Marker)) {
				return filepath.SkipDir
			}
		}
		if m, ok := mainIn(path); ok {
			out = append(out, m)
		}
		return nil
	})
	return out, err
}

// mainIn reports whether dir holds a main package, and whether any of its
// files opts out with //vuka:nolink.
func mainIn(dir string) (mainPkg, bool) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return mainPkg{}, false
	}
	m, isMain := mainPkg{dir: dir}, false
	for _, e := range entries {
		name := e.Name()
		if e.IsDir() || name == LinkGoName ||
			!(strings.HasSuffix(name, ".go") || strings.HasSuffix(name, ".vuka")) ||
			strings.HasSuffix(name, "_test.go") || strings.HasSuffix(name, "_test.vuka") {
			continue
		}
		src, err := os.ReadFile(filepath.Join(dir, name))
		if err != nil {
			continue
		}
		pkg, noLink := packageClause(src)
		if pkg != "main" {
			if pkg != "" {
				return mainPkg{}, false // another package's directory
			}
			continue
		}
		isMain = true
		m.noLink = m.noLink || noLink
	}
	return m, isMain
}

// packageClause is the file's package name, read line by line, and whether a
// //vuka:nolink line comes before the clause. It never parses: a mid-edit
// file simply reads as what its lines say.
func packageClause(src []byte) (name string, noLink bool) {
	inBlock := false
	for _, line := range strings.Split(string(src), "\n") {
		t := strings.TrimSpace(line)
		if inBlock {
			if i := strings.Index(t, "*/"); i >= 0 {
				inBlock, t = false, strings.TrimSpace(t[i+2:])
			} else {
				continue
			}
		}
		switch {
		case t == noLinkDirective:
			noLink = true
		case strings.HasPrefix(t, "package ") || strings.HasPrefix(t, "package\t"):
			f := strings.Fields(t)
			if len(f) >= 2 {
				return strings.TrimSuffix(f[1], ";"), noLink
			}
			return "", noLink
		case strings.HasPrefix(t, "/*"):
			if !strings.Contains(t[2:], "*/") {
				inBlock = true
			}
		}
	}
	return "", noLink
}

// noLink reports whether a //vuka:nolink line comes before the file's
// package clause.
func noLink(src []byte) bool {
	_, no := packageClause(src)
	return no
}
